// Determines the shape/orientation of a room based on its tile coordinates. Returns 0 (invalid), 1 (zero width), 2 (mirrored width), 3 (zero height), or 4 (normal).
int32_t __stdcall DRLGROOM_GetRoomShape(D2RoomStrc * pRoom, int32_t nMode) {
    if (!pRoom) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x17b);
      exit(-1);
    }

    int nLeft = pRoom->sCoords.sTileRect.left;
    int nRight = pRoom->sCoords.sTileRect.right + nLeft;
    if (nLeft > nRight) {
      return 0;
    }

    int nRightEdge = pRoom->sCoords.sTileRect.right + nLeft;
    if (nRightEdge < nLeft) {
      return 0;
    }

    int nTop = pRoom->sCoords.sTileRect.top;
    int nTopPlusHeight = pRoom->sCoords.sTileRect.bottom + nTop;
    if (nTop > nTopPlusHeight || pRoom->sCoords.sTileRect.bottom + nTop < nTop) {
      return 0;
    }
    if (nLeft == nRight) {
      return 1;
    }
    if (nRightEdge == nLeft) {
      return 2;
    }

    return nTop != nTopPlusHeight ? 4 : 3;
}

