// @sourcefile .\DUNGEON\Dungeon.cpp
void __fastcall FreeRoom(D2PoolManagerStrc * pMemory, D2RoomStrc * pRoom) {
    D2UnitStrc* pUnit = pRoom->pUnitList;
    while (pUnit) {
      uint32_t nFlags = pUnit->eUnitFlags;
      if (!FlagBit_D2UnitStrc_eUnitFlags_22(pUnit)) {
        pUnit->eUnitFlagsEx |= 0x20;
      }

      pUnit->eUnitFlags = nFlags | 0x800000;
      Unit::DRLGROOM_ClearUnitRoomLink(pUnit);
      pUnit = pRoom->pUnitList;
    }

    Collision::FreeRoomCollisionGrid(pMemory, pRoom);
    DRLGROOM_FreeDrlgDelete(pRoom);
    if (pRoom->pClients) {
      D2_FREE_POOL_AT(pRoom->pDrlgAct->pMemory, pRoom->pClients, ".\\DUNGEON\\Dungeon.cpp", 0x4e2);
    }

    D2_FREE_POOL_AT(pMemory, pRoom->ppRoomList, ".\\DUNGEON\\Dungeon.cpp", 0x4e4);
    D2_FREE_POOL_AT(pMemory, pRoom, ".\\DUNGEON\\Dungeon.cpp", 0x4e5);
}

