// Converts a bitmask of portal flags (nFlags) into an allocated array of level IDs. Fetches the master portal-level list from LvlTbls; iterates each bit in nFlags, collecting matching level IDs into a stack buffer (max 32). Allocates a server-memory copy of matched IDs into *ppLevels and sets *pnLevels. Outputs null/0 if no bits matched. Halts if the master list exceeds 32 entries.
// @sourcefile .\DUNGEON\Dungeon.cpp
void __stdcall GetPortalLevelArrayFromPortalFlags(D2PoolManagerStrc * pMemory, int32_t nFlags, int * * ppLevels, int * pnLevels) {
    int* pAllocatedLevels;
    eD2LevelId anMatchedLevels[32];
    int nTotalLevels;
    uint32_t dwBitMask = 1;
    int nMatchCount = 0;
    eD2LevelId* pLvlTblsArray = DATATBLS::LvlTbls::GetPortalLevelArrayFromPortalFlags((uint32_t*)&nTotalLevels);
    if (nTotalLevels > 0x20) {
      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x60a);
      exit(-1);
    }

    for (int nBitIdx = 0; nBitIdx < nTotalLevels; nBitIdx++) {
      if (nFlags & dwBitMask) {
        anMatchedLevels[nMatchCount] = pLvlTblsArray[nBitIdx];
        nMatchCount++;
      }

      dwBitMask *= 2;
    }

    if (nMatchCount) {
      pAllocatedLevels = (int*)D2_ALLOC_POOL_AT(pMemory, nMatchCount * 4, ".\\DUNGEON\\Dungeon.cpp", 0x614);
      *ppLevels = pAllocatedLevels;
      memcpy(pAllocatedLevels, anMatchedLevels, nMatchCount * 4);
    } else {
      *ppLevels = 0;
    }
    *pnLevels = nMatchCount;
}

int32_t __stdcall GetPortalFlagFromLevelId(eD2LevelId eLevel) {
    int nArrayCount;
    eD2LevelId* pPortalLevelArray = DATATBLS::LvlTbls::GetPortalLevelArrayFromPortalFlags((uint32_t*)&nArrayCount);
    int nBitIndex = 0;
    if (nArrayCount > 0) {
      do {
        if (eLevel == *pPortalLevelArray) {
          return 1 << D2_SHIFT_COUNT(nBitIndex);
        }

        nBitIndex++;
        pPortalLevelArray++;
      } while (nBitIndex < nArrayCount);
    }

    return 0;
}

